/**
 * Exercises the REAL ffmpeg binary against a REAL compressed file generated by ffmpeg itself
 * (no fake executable, no fabricated provider output). The fast unit tests keep covering the
 * plumbing with a fake binary; this one proves the actual decode path.
 *
 * Skips with a visible reason when ffmpeg is not on PATH; set AURAL_REQUIRE_FFMPEG=1 (the Docker
 * runner does) to make a missing ffmpeg a failure instead.
 */
import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import test from "node:test";
import { SpeechAudioError, decodeSpeechAudio, RELAY_TTS_SAMPLE_RATE } from "../server/speech/audio";
import { createOpenAiCompatibleTtsBackend } from "../server/speech/tts/openai-compatible";
import { startMockServer } from "./helpers/speech-mock-server";

const probe = spawnSync("ffmpeg", ["-version"], { encoding: "utf8" });
const hasFfmpeg = probe.status === 0;
if (!hasFfmpeg && process.env.AURAL_REQUIRE_FFMPEG === "1") {
  test("ffmpeg is required for this run (AURAL_REQUIRE_FFMPEG=1)", () => { assert.fail("ffmpeg not found on PATH"); });
}
const opts = { skip: hasFfmpeg ? false : "ffmpeg is not installed on this host (run via Docker: see HANDOFF.md)" };

const TONE_HZ = 440;
const TONE_SECONDS = 0.5;

function makeMp3(): Buffer {
  const r = spawnSync("ffmpeg", ["-hide_banner", "-loglevel", "error", "-f", "lavfi", "-i", `sine=frequency=${TONE_HZ}:duration=${TONE_SECONDS}:sample_rate=22050`,
    "-ac", "1", "-codec:a", "libmp3lame", "-b:a", "64k", "-f", "mp3", "pipe:1"], { maxBuffer: 10 * 1024 * 1024 });
  assert.equal(r.status, 0, `ffmpeg could not generate the test tone: ${r.stderr?.toString()}`);
  return r.stdout;
}

function analyze(pcm: Buffer) {
  const samples = pcm.length / 2;
  let sumSq = 0, first = -1, last = -1;
  for (let i = 0; i < samples; i++) {
    const v = pcm.readInt16LE(i * 2);
    sumSq += v * v;
    if (Math.abs(v) > 2000) { if (first < 0) first = i; last = i; }
  }
  // Pitch from zero crossings over the audible region only (MP3 encoder padding is near-silent noise).
  let crossings = 0;
  for (let i = first + 1; first >= 0 && i <= last; i++) {
    const p = pcm.readInt16LE((i - 1) * 2), v = pcm.readInt16LE(i * 2);
    if ((p < 0 && v >= 0) || (p >= 0 && v < 0)) crossings++;
  }
  const activeSeconds = (last - first) / RELAY_TTS_SAMPLE_RATE;
  return { samples, seconds: samples / RELAY_TTS_SAMPLE_RATE, rms: Math.sqrt(sumSq / samples), hz: activeSeconds > 0 ? crossings / 2 / activeSeconds : 0 };
}

test("real ffmpeg decodes a real MP3 into valid mono 24 kHz s16le PCM with the expected duration and pitch", opts, async () => {
  const mp3 = makeMp3();
  assert.ok(mp3.length > 1000 && mp3.length < 50_000, `generated a small real mp3 (${mp3.length} B)`);
  assert.ok(mp3.subarray(0, 3).toString("latin1") === "ID3" || (mp3[0] === 0xff && (mp3[1] & 0xe0) === 0xe0), "mp3 magic bytes");

  const pcm = await decodeSpeechAudio(mp3, { format: "mp3" });
  assert.equal(pcm.length % 2, 0, "whole 16-bit samples");
  const a = analyze(pcm);
  // MP3 adds encoder delay/padding (tens of ms); duration must still be close to the source.
  assert.ok(a.seconds >= TONE_SECONDS - 0.05 && a.seconds <= TONE_SECONDS + 0.12, `duration ${a.seconds.toFixed(3)}s`);
  assert.ok(a.rms > 2000 && a.rms < 32000, `audible, unclipped signal (rms ${a.rms.toFixed(0)})`);
  assert.ok(Math.abs(a.hz - TONE_HZ) < 15, `dominant pitch ${a.hz.toFixed(1)} Hz ≈ ${TONE_HZ} Hz (proves resampling 22.05k→24k kept pitch)`);
  console.log(`# real ffmpeg: ${probe.stdout.split("\n")[0]} | mp3 ${mp3.length} B -> ${pcm.length} B PCM, ${a.seconds.toFixed(3)} s, rms ${a.rms.toFixed(0)}, ${a.hz.toFixed(1)} Hz`);
});

test("real ffmpeg rejects non-audio bytes instead of producing fabricated output", opts, async () => {
  await assert.rejects(decodeSpeechAudio(Buffer.from("this is definitely not audio, just text".repeat(20)), { format: "mp3" }),
    (e: unknown) => e instanceof SpeechAudioError && /ffmpeg/.test(e.message));
});

test("real ffmpeg honours the output cap", opts, async () => {
  await assert.rejects(decodeSpeechAudio(makeMp3(), { format: "mp3", maxOutputBytes: 1000 }), (e: unknown) => e instanceof SpeechAudioError && /size limit/.test(e.message));
});

test("TTS backend serves a real MP3 from a loopback provider through real ffmpeg to browser PCM", opts, async () => {
  const mp3 = makeMp3();
  const server = await startMockServer((_req, res) => { res.setHeader("content-type", "audio/mpeg"); res.end(mp3); });
  try {
    const backend = createOpenAiCompatibleTtsBackend({ baseUrl: `${server.baseUrl}/v1`, model: "m", voice: "v", format: "mp3", pcmSampleRate: 24000, timeoutMs: 10_000, maxAudioBytes: 1_000_000, maxSegments: 4 });
    const file = await backend.synthesizeFile({ text: "Hello." }, "wav");
    assert.ok(file && file.format === "wav");
    const a = analyze(file.audio.subarray(44));
    assert.ok(a.seconds > 0.4 && a.seconds < 0.7 && Math.abs(a.hz - TONE_HZ) < 15, `${a.seconds}s ${a.hz}Hz`);
  } finally { await server.close(); }
});
